; 2026-10-16 (runs/maps-pm mkmaps3.py): font-pairing picks 2(TC)=paperfb-paperb-18-aa, 4(TC)=marufb-marub-24-aa, 6(TC)=marufb-marub-20-aa, 8(TC)=paperfb-paperb-16-aa (first in the chain; English original)
# Monkey Island 2 (mi2kor Korean patch). One map, two presets; the ini's
# render_target picks one.
#   Default (true colour: render_target=auto, on DOS rgb565 unless only rgb888 has 640x400; or set rgb565 or rgb888): NanumGothic Bold (NGOTB*) and Gowun Batang Bold (GBATB*) faces, 2 bpp,
#   anti-aliased (blend=auto), baked by tools/korean/scumm-fonts/m2u.tsv:
#   dialogue, verbs and the sentence line in a gothic face, the title/credit
#   card in a serif face. With them in the bare sections, render_target=auto
#   picks true colour.
#   render_target=clut8 (8-bit palette): 1 bpp faces, drawn hard-edged: NEODG16B is a pixel
#   face and NGOTB17 (dialogue) NanumGothic Bold hinted at 17 px, baked by tools/korean/scumm-fonts/m2l.tsv, and the 24 px tall cells (TBGOB24, TBMY24; cs7 shares TBMY24) a real 24 dot
#   DOS Hangul face (Taebaek jamo set, jamoset.py --layout 844-hbios24), 24x24 cells that step as the game's cell does.
# Cells per charset: cs0/cs6 22x24, cs1/cs3/cs5/cs8 16x16, cs2 18x18, cs4 26x24,
# cs7 24x24; both presets bake the same cells. Charsets that share a cell share
# one SVF; the 2 bpp set bakes charset 8 on its own (GBATB14.SVF), the 1 bpp set
# serves it with the charset 1 file.
# MI2 draws its verb line in charset 6, which has no korean06.fnt: it uses the
# charset 0 file. Licences: see NANUMGOT.TXT, GOWUNBAT.TXT, NEODGM.TXT and TAEBAEK.TXT beside this file.
[map]
version=2

[render]
scale=2
blend=auto
[render:clut8]
blend=off

[text]
encoding=cp949

# Every base face holds ASCII and the 2,350 KS X 1001 syllables (the Taebaek jamo sets compose all 11,172); the
# X face chained after it, baked by tools/korean/scumm-fonts/m2x.tsv, holds only what the text draws beyond that
# (a-circumflex and e-acute of "Papier-Mache", the ellipsis and trademark sign the map remaps to). Same cell and
# baseline as its base.
[fonts]
dlg=NGOTB21A.SVF
small=NGOTB15.SVF
sent=NGOTB16B.SVF
card=GBATB23A.SVF
card7=GBATB23.SVF
card8=GBATB14.SVF
dlgx=NGO21AX2.SVF
smallx=NGO15X2.SVF
sentx=NGO16BX2.SVF
cardx=GBA23AX2.SVF
card7x=GBA23X2.SVF
card8x=GBA14X2.SVF
paplb18a=PAPLB18A.SVF
marub24a=MARUB24A.SVF
marub20a=MARUB20A.SVF
paplb16a=PAPLB16A.SVF
[fonts:clut8]
dlg=TBGOB24.SVF
small=NEODG16B.SVF
sent=NGOTB17.SVF
card=TBMY24.SVF
card7=TBMY24.SVF
card8=NEODG16B.SVF
dlgx=TBG24X2.SVF
smallx=NEO16BX2.SVF
sentx=NGO17X2.SVF
cardx=TBM24X2.SVF
card7x=TBM24X2.SVF
card8x=NEO16BX2.SVF
fb=SANGAM16.SVF

# True colour keeps the three card faces (GBATB23A 440 KB, GBATB23 382 KB, GBATB14 186 KB) in their files instead of
# in memory: [load] streams them. GBATB23A and GBATB14 (title, credits, difficulty cards) also get a [preload] list,
# the characters the game draws with them (the .HOT files beside this map, made by tools/korean/charsetchars.py,
# see SCUMM_FONTS.md): read at start, they are then in the cache and anything else comes from the file when it
# is drawn. Charset 7 is drawn with some 1,000 syllables by that analysis, enough to read all of GBATB23 at start and
# hold more than the whole face (a cache entry keeps two cells), so card7 is only streamed; GBATB23.HOT is shipped
# for a try (card7=GBATB23.HOT). The 8-bit faces are small (20-38 KB): whole, as before.
[load]
card=stream
card7=stream
card8=stream
[load:clut8]
card=auto
card7=auto
card8=auto
[preload]
card=GBATB23A.HOT
#card7=GBATB23.HOT
card8=GBATB14.HOT
[preload:clut8]
card=
card8=

[font]
missing=u+25a1
# ASCII from each charset's own SVF (never the game's internal font),
# stepped by the face's own widths
range.basic-latin=same
advance.basic-latin=font
# The card fonts (charsets 4, 7, 8) are trimmed: '.' and ',' carry a game offsY of 9 in a
# 15 px cell. The baked SVF already sets the baseline, so drop the game's offsets; the
# remapped ellipsis (below) follows the letters around it.
origin.basic-latin=face
origin.general-punctuation=face

[font.0]
face=dlg,dlgx
[font.1]
face=small,smallx
[font.2]
face=paplb18a,sent,sentx
range.basic-latin=original
advance.basic-latin=game
origin.basic-latin=game
[font.2:clut8]
face=sent,sentx
range.basic-latin=same
advance.basic-latin=font
origin.basic-latin=face
[font.3]
face=small,smallx
[font.4]
face=marub24a,card,cardx
range.basic-latin=original
advance.basic-latin=game
origin.basic-latin=game
[font.5]
face=small,smallx
[font.6]
face=marub20a,dlg,dlgx
range.basic-latin=original
advance.basic-latin=game
origin.basic-latin=game
[font.7]
face=card7,card7x
[font.8]
face=paplb16a,card8,card8x

# fb=SANGAM16.SVF (engine data, SAN10.TXT) ends each chain of a face that lives in the jamo font pack, so a missing
# font pack still shows Korean (16 px; only the 8-bit preset has jamo-set faces).
# The jamo-set faces (TBGOB24, NEODG16B, TBMY24) come from the font pack. fb is last after the 16 px faces (NEODG16B: the
# supplement draws its own characters, not fb) but before the supplement of the 24 px faces: without the pack
# a 24 px supplement alone would set the cell height and drop the 16 px fb (the supplement's two glyphs are
# lost then; with the pack present fb is dropped there anyway, its height differs).
range.basic-latin=original
advance.basic-latin=game
origin.basic-latin=game
[font.0:clut8]
face=dlg,fb,dlgx
[font.1:clut8]
face=small,smallx,fb
[font.3:clut8]
face=small,smallx,fb
[font.4:clut8]
face=card,fb,cardx
range.basic-latin=same
advance.basic-latin=font
origin.basic-latin=face
[font.5:clut8]
face=small,smallx,fb
[font.6:clut8]
face=dlg,fb,dlgx
range.basic-latin=same
advance.basic-latin=font
origin.basic-latin=face
[font.7:clut8]
face=card7,fb,card7x
[font.8:clut8]
face=card8,card8x,fb

# MI2's own pictogram: the skull-and-crossbones dialogue bullet at 0x07 (always the
# first byte of a spoken line in korean.trs; no Latin face has anything for it) stays
# the game's glyph.
# Everything else the patch parked on an odd byte code is real punctuation and is
# drawn by the replacement font like any other character:
#   0x5e ellipsis (every occurrence in korean.trs trails a clause: "..." / trailing off)
#   0x5c exclamation mark (korean.trs: "원해!  모든 퍼즐!  온갖 생고생!")
#   0x60 double quote, both opening and closing (one byte serves both roles in the text,
#     so there is no separate open/close code to distinguish)
#   0x0f trademark sign (korean.trs: "Ash-2-Life\x0f")
range.basic-latin=same
advance.basic-latin=font
origin.basic-latin=face
[glyphs]
0x07 = original
0x5e = u+2026
0x5c = u+0021
0x60 = u+0022
0x0f = u+2122

# neodgm, the L preset's pixel face, has no ™ glyph; its own 1 bpp 0x0f matches the
# hard-edged L look, so clut8 keeps the game's own glyph instead of falling back to the
# missing-glyph box.
[glyphs:clut8]
0x0f = original
